package org.apache.commons.lang3;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.apache.commons.lang3.builder.EqualsBuilder;
import org.apache.commons.lang3.builder.ToStringBuilder;
import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ArrayUtils.add(T[] array, T element)
 */
public class ArrayUtils_add_TriageGen4Test {

    @Test
    public void testAdd_WithExistingArray() {
        String[] input = {"a", "b"};
        String element = "c";
        String[] expected = {"a", "b", "c"};
        String[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
        assertEquals(3, result.length);
        // Ensure original array is not modified (defensive copy check)
        assertEquals(2, input.length);
    }

    @Test
    public void testAdd_WithNullArrayAndNonNullElement() {
        // Covers branch: if (array != null) -> false; else if (element != null) -> true
        Integer element = 5;
        Integer[] result = ArrayUtils.add(null, element);

        assertNotNull(result);
        assertEquals(1, result.length);
        assertEquals(Integer.valueOf(5), result[0]);
    }

    @Test
    public void testAdd_WithNullArrayAndNullElement() {
        // Covers branch: if (array != null) -> false; else if (element != null) -> false; else -> Object.class
        Object[] result = ArrayUtils.add(null, null);

        assertNotNull(result);
        assertEquals(1, result.length);
        assertNull(result[0]);
    }

    @Test
    public void testAdd_WithEmptyArray() {
        String[] input = {};
        String element = "new";
        String[] expected = {"new"};
        String[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_WithIntegerArray() {
        Integer[] input = {1, 2};
        Integer element = 3;
        Integer[] expected = {1, 2, 3};
        Integer[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_WithDoubleArray() {
        Double[] input = {1.1, 2.2};
        Double element = 3.3;
        Double[] expected = {1.1, 2.2, 3.3};
        Double[] result = ArrayUtils.add(input, element);

        assertArrayEquals(expected, result);
    }

    @Test
    public void testAdd_MaintainsType() {
        // Verifies that the returned array is of the same component type
        Long[] input = {1L, 2L};
        Long element = 3L;
        Long[] result = ArrayUtils.add(input, element);

        assertTrue(java.lang.reflect.Array.newInstance(Long.class, 1).getClass().isArray());
        assertEquals(Long.class, result.getClass().getComponentType());
    }
}
